    tool = str(event.get("tool_name") or event.get("toolName") or "")
    if tool not in WRITE_TOOLS:
        return 0
    ti = event.get("tool_input") or event.get("toolInput") or {}
    if isinstance(ti, str):
        try:
            ti = json.loads(ti)
        except json.JSONDecodeError:
