            Err(ReplyError::Exception(ExceptionCode::ILLEGAL_DATA_ADDRESS))
        );
        assert!(matches!(
            decode_read_response(&r, &[0x04, 0x04, 0, 1, 0, 2]),
            Err(ReplyError::Frame(FrameError::ByteCount { expected: 2, received: 4 }))
        ));
