        let mut f = framer();
        let frame = encode_adu(2, &[0x03, 0x02, 0x01, 0x0A]).unwrap();
        assert_eq!(f.push(&frame), FramerStatus::Complete(Err(FrameError::WrongUnit { expected: 1, received: 2 })));
    }

    #[test]
