        let frame = encode_adu(1, &[0x03, 0x02, 0x01, 0x0A]).unwrap();
        assert_eq!(f.push(&frame), FramerStatus::Complete(Ok(vec![0x03, 0x02, 0x01, 0x0A])));
    }

