        let frame = encode_adu(1, &[0x83, 0x02]).unwrap();
        assert_eq!(frame.len(), 5);
        assert_eq!(f.push(&frame[..3]), FramerStatus::NeedMore(2));
        assert_eq!(f.push(&frame[3..]), FramerStatus::Complete(Ok(vec![0x83, 0x02])));
    }

