        let mut f = ResponseFramer::new(7, 0x2A, ExpectedReply::Fixed(4));
        let mut frame = encode_adu(7, &[0x2A, 1, 2, 3, 4]).unwrap();
        frame.extend_from_slice(&[0xEE, 0xEE]);
