    let mut files = Vec::new();
    let mut n = 0u32;
    check("profile_agreement_mutated", 400, |r| {
        let mut d = r.pick(&docs).unwrap().clone();
        for _ in 0..r.range_u64(1, 3) {
            mutate(r, &mut d, 0);
