    let rec2 = ex.transact(&mut t, 1, Outgoing::Read(&req), 500);
    assert!(rec2.outcome.is_ok());
    let w = h.writes();
    assert_ne!(w[0].1[..2], w[1].1[..2], "transaction IDs advance");
}

