use buslink_core::profile::{self, Profile};
use buslink_core::protocol::rtu::SerialSettings;
use buslink_core::quality::Sample;
use buslink_core::transport::Transport;
use std::path::Path;

pub fn bundled(name: &str) -> Profile {
