    let mut p2 = (*p).clone();
    p2.registers.push(register("missing", Table::HoldingRegister, 100, TypeName::U16, None));
    let (mut s, mut t, _h, clock) = sched_with(&bus, vec![(d, Arc::new(p2))]);
    let mut out = Vec::new();
    run_until(&mut s, &mut t, &clock, 2_500, &mut out);
    assert!(out.iter().any(|x| x.tag_id == "missing" && x.quality == Quality::Exception(2)));
    assert_eq!(good_times(&out, "soil").len(), 3);
    assert_eq!(s.counters()[0].1.consecutive_failures, 0, "exceptions do not back off a live device");
}

