const SOIL: [(u16, u16); 8] = [(0, 253), (1, 312), (2, 480), (3, 260), (4, 35), (5, 12), (6, 80), (7, 680)];

fn soil_device(id: &str, unit: u8, interval: u64, link: &buslink_core::device::LinkConfig) -> (DeviceInstance, Arc<Profile>) {
    let p = Arc::new(bundled("bgt-smps-8in1.json"));
