const SOIL: [(u16, u16); 8] = [(0, 253), (1, 312), (2, 480), (3, 260), (4, 35), (5, 12), (6, 80), (7, 680)];

fn soil_device(id: &str, unit: u8, interval: u64, link: &buslink_core::device::LinkConfig) -> (DeviceInstance, Arc<Profile>) {
    let p = Arc::new(bundled("bgt-smps-8in1.json"));
    let mut d = DeviceInstance::from_profile(id, id, link, &p);
    d.unit_id = unit;
    d.poll_interval_ms = interval;
    (d, p)
}

fn register(id: &str, table: Table, address: u16, ty: TypeName, length: Option<u16>) -> Register {
    Register {
        id: id.into(),
        name: Text::Plain(id.into()),
        description: None,
        table,
        address,
        doc_address: None,
        type_name: ty,
        length,
        word_order: if matches!(ty, TypeName::U32 | TypeName::F32 | TypeName::U64 | TypeName::F64) {
            Some(buslink_core::codec::WordOrder::ABCD)
        } else {
            None
        },
        scale: None,
        offset: None,
        unit: None,
        decimals: None,
        valid_range: None,
        invalid_sentinels: None,
        bits: None,
        access: Access::Read,
        write: None,
        poll: None,
        source_page: None,
    }
}

